# -*- coding: utf-8 -*-
import os as _os
ROOT = _os.path.dirname(_os.path.dirname(_os.path.abspath(__file__)))
P = _os.environ.get("PLOOM_PROJECT", _os.path.join(ROOT, "ref"))
import pandas as pd, json, os
pd.set_option("display.width", 230); pd.set_option("display.max_columns", 40); pd.set_option("display.max_rows", 300)
D = _os.path.join(ROOT, "work", "data", "out")
s = pd.read_csv(os.path.join(D, "long_sales.csv")); t = pd.read_csv(os.path.join(D, "long_storeday.csv"))
def sec(x): print("\n" + "="*8, x, "="*8)
s["요일"] = pd.to_datetime(s["일자"]).dt.day_of_week
s["팀일"] = s["일자"] + "_" + s["팀"].astype(str)
sec("월별 종합")
m = s.groupby("월").agg(판매=("수량","sum"), 일수=("일자","nunique"), 판매팀수=("팀","nunique"), 판매팀일=("팀일","nunique"), 점포수=("점포코드","nunique"), 스타벅스=("스타벅스","sum"))
m["일평균"] = m["판매"]/m["일수"]; m["팀일당"] = m["판매"]/m["판매팀일"]; m["점포당"] = m["판매"]/m["점포수"]
print(m.round(2))
sec("월별 인력사"); x = s.groupby(["월","인력사"]).agg(판매=("수량","sum"), 팀일=("팀일","nunique"), 팀수=("팀","nunique")); x["팀일당"]=(x["판매"]/x["팀일"]).round(2); print(x.unstack(1).round(2))
sec("방문점포(storeday) 월별"); tt = t.groupby("월").agg(점포일=("점포코드","size"), 무판매=("판매량", lambda v:(v==0).sum()), 판매량=("판매량","sum"), 점포수=("점포코드","nunique")); tt["무판매율"]=(tt["무판매"]/tt["점포일"]*100).round(1); tt["점포일당"]=(tt["판매량"]/tt["점포일"]).round(2); print(tt)
sec("요일"); w = s.groupby("요일").agg(판매=("수량","sum"), 일수=("일자","nunique")); w["일평균"]=(w["판매"]/w["일수"]).round(1); print(w)
sec("시간대 월별 비중(%)"); h = s[(s["시"]>=9)&(s["시"]<=19)].pivot_table(index="시", columns="월", values="수량", aggfunc="sum", fill_value=0); print((h/h.sum()*100).round(1))
sec("점포구분 월별 비중"); x = s.pivot_table(index="월", columns="점포구분", values="수량", aggfunc="sum", fill_value=0); print(x); print((x.div(x.sum(1), axis=0)*100).round(1))
sec("브랜드 월별"); x = s[s["점포타입"].isin(["CU","세븐일레븐","GS25","이마트24"])].pivot_table(index="월", columns="점포타입", values="수량", aggfunc="sum", fill_value=0); print((x.div(x.sum(1), axis=0)*100).round(1))
x = s.groupby(["점포구분","점포타입"]).agg(판매=("수량","sum"), 점포수=("점포코드","nunique"), 점포일=("일자", "size")); x["점포당"]=(x["판매"]/x["점포수"]).round(2); print(x.sort_values("판매", ascending=False).head(8))
sec("색상 월별 비중"); x = s.pivot_table(index="월", columns="색상", values="수량", aggfunc="sum", fill_value=0); print((x.div(x.sum(1), axis=0)*100).round(1))
sec("판매경로 월별"); x = s.pivot_table(index="월", columns="판매경로", values="수량", aggfunc="sum", fill_value=0); print(x)
sec("차용 월별"); print(s.pivot_table(index="월", columns="차용", values="수량", aggfunc="sum", fill_value=0))
sec("회원가입/카카오 월별 완료율"); print(s.groupby("월").apply(lambda g: pd.Series({"회원가입완료": (g["회원가입"].astype(str).str.contains("완료") & ~g["회원가입"].astype(str).str.contains("미완료")).mean()*100, "카카오완료": (g["카카오"].astype(str).str.contains("완료") & ~g["카카오"].astype(str).str.contains("미완료")).mean()*100})).round(1))
sec("스타벅스 건당 월별"); print(s.groupby("월").apply(lambda g: (g["스타벅스"].sum()/g["수량"].sum())).round(2))
sec("고객 (8월~)"); g = s[s["성별"].notna()]; print(g.pivot_table(index="월", columns="성별", values="수량", aggfunc="sum", fill_value=0)); x = g.pivot_table(index="월", columns="연령대", values="수량", aggfunc="sum", fill_value=0); print((x.div(x.sum(1), axis=0)*100).round(1))
g = g.copy(); g["주사용"] = g["사용제품"].astype(str).str.split(",").str[0].str.strip(); x = g.pivot_table(index="월", columns="주사용", values="수량", aggfunc="sum", fill_value=0); print((x.div(x.sum(1), axis=0)*100).round(1))
sec("리필스틱 월별 동반율"); r = s[s["리필스틱"].notna()]; print(r.groupby("월").apply(lambda g: g["리필구매"].mean()*100).round(1))
sec("점포 누적"); st = s.groupby(["점포코드"]).agg(판매=("수량","sum"), 일수=("일자","nunique"), 첫달=("월","min"), 마지막달=("월","max"), 팀수=("팀","nunique"), 점포명=("점포명","first"), 타입=("점포타입","first"), 구분=("점포구분","first"))
print("점포수", len(st)); print(st["일수"].describe()); print(st.sort_values("판매", ascending=False).head(20))
print("판매 집중도: 상위 10% 점포 판매 비중", round(st.sort_values("판매", ascending=False).head(len(st)//10)["판매"].sum()/st["판매"].sum()*100,1), "%; 상위 50 점포", round(st.sort_values("판매", ascending=False).head(50)["판매"].sum()/st["판매"].sum()*100,1))
sec("방문 차수별 일평균 (전 기간)"); sp = s.groupby(["점포코드","일자"])["수량"].sum().reset_index(); sp["차수"]=sp.groupby("점포코드").cumcount()+1; sp["차수구간"]=pd.cut(sp["차수"],[0,1,2,3,5,10,20,999],labels=["1","2","3","4-5","6-10","11-20","21+"]); print(sp.groupby("차수구간", observed=True)["수량"].agg(["size","mean"]).round(2))
sec("월별 신규 점포 vs 재방문 점포 판매"); first = s.groupby("점포코드")["월"].min(); s["신규"] = s["점포코드"].map(first) == s["월"]; x = s.pivot_table(index="월", columns="신규", values="수량", aggfunc="sum", fill_value=0); x.columns=["재방문점포","신규점포"]; x["신규비중%"]=(x["신규점포"]/x.sum(1)*100).round(1); print(x); print(s.groupby(["월","신규"])["점포코드"].nunique().unstack())
sec("지역 월별"); stores = pd.DataFrame(json.load(open(os.path.join(P,"stores.json"),encoding="utf-8"))).drop_duplicates("k"); stores["시도"]=stores["a"].astype(str).str.split().str[0].replace({"경기도":"경기","서울시":"서울","서울특별시":"서울"}); stores["시군구"]=stores["a"].astype(str).str.split().str[1]
s = s.merge(stores[["k","시도","시군구"]].rename(columns={"k":"점포코드"}), on="점포코드", how="left"); print("주소 매칭률", s["시도"].notna().mean().round(3)); x = s.pivot_table(index="월", columns="시도", values="수량", aggfunc="sum", fill_value=0); print(x[["서울","경기","인천"]] if "인천" in x else x)
print(s.groupby("시군구")["수량"].sum().sort_values(ascending=False).head(15))
sec("추천점포 vs 비추천 (전 기간, 월별 점포당)"); rec = pd.DataFrame(json.load(open(os.path.join(P,"recommend_points.json"),encoding="utf-8"))); s["추천"]=s["점포코드"].isin(set(rec["k"])); x = s.groupby(["월","추천"]).agg(판매=("수량","sum"), 점포수=("점포코드","nunique")); x["점포당"]=(x["판매"]/x["점포수"]).round(2); print(x.unstack(1))
sec("에이전트 누적 상위"); a = s.groupby(["인력사","에이전트"]).agg(판매=("수량","sum"), 일수=("일자","nunique"), 월수=("월","nunique")); a["일당"]=(a["판매"]/a["일수"]).round(2); print(a[a["일수"]>=20].sort_values("일당", ascending=False).head(15)); print("에이전트 수", len(a), " 20일 이상", (a["일수"]>=20).sum())
sec("팀 월별 지속"); tm = s.groupby(["월","인력사"])["팀"].unique(); print(tm.apply(lambda v: f"{len(v)}팀 {min(v):.0f}~{max(v):.0f}"))
sec("일자별 상위/하위"); d = s.groupby("일자")["수량"].sum(); print(d.sort_values(ascending=False).head(5)); print(d.sort_values().head(5))
s.to_csv(os.path.join(D, "long_sales_enriched.csv"), index=False, encoding="utf-8-sig")
